`timescale 1ns / 1ps
`default_nettype none

// axil_timer: 32-bit down-counting timer with one-shot and periodic modes
// and a level interrupt, behind an AXI4-Lite subordinate port.
//
// Implements interface_spec.md / microarchitecture.md (rtl/axil-timer).
//
// Register map (byte offsets):
//   0x0 CTRL   rw   bit0 EN, bit1 IE, bit2 MODE (0 one-shot, 1 periodic)
//   0x4 LOAD   rw   count length in cycles (0 counts as 1)
//   0x8 COUNT  ro   cycles left; a write gets SLVERR and changes nothing
//   0xC STATUS w1c  bit0 EXPIRED
// Unaligned addresses and, for ADDR_WIDTH > 4, every offset from 0x10 up
// are unmapped: writes change nothing and get SLVERR, reads return zero
// with SLVERR.

module axil_timer #(
    parameter integer ADDR_WIDTH = 4
) (
    input  wire                  aclk,
    input  wire                  aresetn,

    input  wire [ADDR_WIDTH-1:0] s_axil_awaddr,
    input  wire                  s_axil_awvalid,
    output wire                  s_axil_awready,

    input  wire [31:0]           s_axil_wdata,
    input  wire [3:0]            s_axil_wstrb,
    input  wire                  s_axil_wvalid,
    output wire                  s_axil_wready,

    output reg  [1:0]            s_axil_bresp,
    output reg                   s_axil_bvalid,
    input  wire                  s_axil_bready,

    input  wire [ADDR_WIDTH-1:0] s_axil_araddr,
    input  wire                  s_axil_arvalid,
    output wire                  s_axil_arready,

    output reg  [31:0]           s_axil_rdata,
    output reg  [1:0]            s_axil_rresp,
    output reg                   s_axil_rvalid,
    input  wire                  s_axil_rready,

    output wire                  irq
);

    localparam [1:0] RESP_OKAY   = 2'b00;
    localparam [1:0] RESP_SLVERR = 2'b10;

    localparam [1:0] IDX_CTRL    = 2'd0;
    localparam [1:0] IDX_LOAD    = 2'd1;
    localparam [1:0] IDX_COUNT   = 2'd2;
    localparam [1:0] IDX_STATUS  = 2'd3;

    // ------------------------------------------------------------------
    // Timer state
    // ------------------------------------------------------------------
    reg        en;
    reg        ie;
    reg        mode;
    reg        expired;
    reg [31:0] load;
    reg [31:0] count;

    // ------------------------------------------------------------------
    // Write channels
    // ------------------------------------------------------------------
    reg                  aw_held;
    reg                  w_held;
    reg [ADDR_WIDTH-1:0] aw_addr_q;
    reg [31:0]           w_data_q;
    reg [3:0]            w_strb_q;

    assign s_axil_awready = !aw_held && !s_axil_bvalid;
    assign s_axil_wready  = !w_held  && !s_axil_bvalid;

    wire aw_hs    = s_axil_awvalid && s_axil_awready;
    wire w_hs     = s_axil_wvalid  && s_axil_wready;
    wire do_write = (aw_held || aw_hs) && (w_held || w_hs);

    wire [ADDR_WIDTH-1:0] wr_addr = aw_held ? aw_addr_q : s_axil_awaddr;
    wire [31:0]           wr_data = w_held  ? w_data_q  : s_axil_wdata;
    wire [3:0]            wr_strb = w_held  ? w_strb_q  : s_axil_wstrb;

    // ------------------------------------------------------------------
    // Address decode: mapped only when word aligned and below 0x10
    // ------------------------------------------------------------------
    wire wr_hi_zero;
    wire rd_hi_zero;

    generate
        if (ADDR_WIDTH > 4) begin : g_wide_addr
            assign wr_hi_zero = (wr_addr[ADDR_WIDTH-1:4]       == {(ADDR_WIDTH-4){1'b0}});
            assign rd_hi_zero = (s_axil_araddr[ADDR_WIDTH-1:4] == {(ADDR_WIDTH-4){1'b0}});
        end else begin : g_narrow_addr
            assign wr_hi_zero = 1'b1;
            assign rd_hi_zero = 1'b1;
        end
    endgenerate

    wire       wr_mapped = (wr_addr[1:0] == 2'b00) && wr_hi_zero;
    wire [1:0] wr_idx    = wr_addr[3:2];
    wire       wr_ok     = wr_mapped && (wr_idx != IDX_COUNT);

    wire wr_ctrl   = do_write && wr_mapped && (wr_idx == IDX_CTRL);
    wire wr_load   = do_write && wr_mapped && (wr_idx == IDX_LOAD);
    wire wr_status = do_write && wr_mapped && (wr_idx == IDX_STATUS);

    wire ctrl_wr    = wr_ctrl && wr_strb[0];
    wire status_clr = wr_status && wr_strb[0] && wr_data[0];

    always @(posedge aclk) begin
        if (!aresetn) begin
            aw_held       <= 1'b0;
            w_held        <= 1'b0;
            aw_addr_q     <= {ADDR_WIDTH{1'b0}};
            w_data_q      <= 32'd0;
            w_strb_q      <= 4'd0;
            s_axil_bvalid <= 1'b0;
            s_axil_bresp  <= RESP_OKAY;
        end else begin
            if (s_axil_bvalid && s_axil_bready) begin
                s_axil_bvalid <= 1'b0;
            end
            if (aw_hs) begin
                aw_addr_q <= s_axil_awaddr;
            end
            if (w_hs) begin
                w_data_q <= s_axil_wdata;
                w_strb_q <= s_axil_wstrb;
            end
            if (do_write) begin
                aw_held       <= 1'b0;
                w_held        <= 1'b0;
                s_axil_bvalid <= 1'b1;
                s_axil_bresp  <= wr_ok ? RESP_OKAY : RESP_SLVERR;
            end else begin
                if (aw_hs) begin
                    aw_held <= 1'b1;
                end
                if (w_hs) begin
                    w_held <= 1'b1;
                end
            end
        end
    end

    // ------------------------------------------------------------------
    // Read channels
    // ------------------------------------------------------------------
    assign s_axil_arready = !s_axil_rvalid;

    wire ar_hs     = s_axil_arvalid && s_axil_arready;
    wire rd_mapped = (s_axil_araddr[1:0] == 2'b00) && rd_hi_zero;

    reg [31:0] rd_val;
    always @(*) begin
        case (s_axil_araddr[3:2])
            IDX_CTRL:  rd_val = {29'd0, mode, ie, en};
            IDX_LOAD:  rd_val = load;
            IDX_COUNT: rd_val = count;
            default:   rd_val = {31'd0, expired};
        endcase
    end

    always @(posedge aclk) begin
        if (!aresetn) begin
            s_axil_rvalid <= 1'b0;
            s_axil_rdata  <= 32'd0;
            s_axil_rresp  <= RESP_OKAY;
        end else begin
            if (s_axil_rvalid && s_axil_rready) begin
                s_axil_rvalid <= 1'b0;
            end
            if (ar_hs) begin
                s_axil_rvalid <= 1'b1;
                s_axil_rdata  <= rd_mapped ? rd_val : 32'd0;
                s_axil_rresp  <= rd_mapped ? RESP_OKAY : RESP_SLVERR;
            end
        end
    end

    // ------------------------------------------------------------------
    // Timer. Order gives the specified priorities (last assignment wins):
    //   1. count step, 2. expired clear then set, 3. CTRL write, 4. LOAD.
    // ------------------------------------------------------------------
    wire count_end = en && (count <= 32'd1);

    always @(posedge aclk) begin
        if (!aresetn) begin
            en      <= 1'b0;
            ie      <= 1'b0;
            mode    <= 1'b0;
            expired <= 1'b0;
            load    <= 32'd0;
            count   <= 32'd0;
        end else begin
            // 1. Count step
            if (count_end) begin
                if (mode) begin
                    count <= load;
                end else begin
                    count <= 32'd0;
                    en    <= 1'b0;
                end
            end else if (en) begin
                count <= count - 32'd1;
            end

            // 2. Expiry: a count end beats a clear
            if (status_clr) begin
                expired <= 1'b0;
            end
            if (count_end) begin
                expired <= 1'b1;
            end

            // 3. CTRL write wins for en and count
            if (ctrl_wr) begin
                ie   <= wr_data[1];
                mode <= wr_data[2];
                if (wr_data[0]) begin
                    en    <= 1'b1;
                    count <= load;
                end else begin
                    en    <= 1'b0;
                end
            end

            // 4. LOAD byte merge
            if (wr_load) begin
                if (wr_strb[0]) load[7:0]   <= wr_data[7:0];
                if (wr_strb[1]) load[15:8]  <= wr_data[15:8];
                if (wr_strb[2]) load[23:16] <= wr_data[23:16];
                if (wr_strb[3]) load[31:24] <= wr_data[31:24];
            end
        end
    end

    assign irq = expired && ie;

    // ------------------------------------------------------------------
    // Design-intent assertions (not part of synthesis or simulation)
    // ------------------------------------------------------------------
`ifdef FORMAL
    reg f_reset_seen = 1'b0;
    always @(posedge aclk) begin
        if (!aresetn) begin
            f_reset_seen <= 1'b1;
        end
    end

    always @(*) begin
        if (f_reset_seen) begin
            // Never both halves held: the second half completes the write.
            assert (!(aw_held && w_held));
            // While a response waits, nothing is held.
            if (s_axil_bvalid) begin
                assert (!aw_held && !w_held);
            end
            // Only OKAY or SLVERR are ever returned.
            assert (s_axil_bresp == RESP_OKAY || s_axil_bresp == RESP_SLVERR);
            assert (s_axil_rresp == RESP_OKAY || s_axil_rresp == RESP_SLVERR);
            // The interrupt is a plain AND of two flops.
            assert (irq == (expired && ie));
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
