// Top-level testbench for axil_timer. Runs the directed test lane at
// ADDR_WIDTH 4 and at ADDR_WIDTH 8, sums their check counts, prints the
// verdict once and ends the simulation.
module axil_timer_tb;

    reg aclk = 1'b0;
    always #5 aclk = ~aclk;

    wire        done4;
    wire        done8;
    wire [31:0] passed4;
    wire [31:0] failed4;
    wire [31:0] passed8;
    wire [31:0] failed8;

    axil_timer_tb_lane #(.ADDR_WIDTH(4)) u_lane4 (
        .aclk   (aclk),
        .done   (done4),
        .passed (passed4),
        .failed (failed4)
    );

    axil_timer_tb_lane #(.ADDR_WIDTH(8)) u_lane8 (
        .aclk   (aclk),
        .done   (done8),
        .passed (passed8),
        .failed (failed8)
    );

    reg [8*64-1:0] nonce;
    integer        passed;
    integer        failed;
    integer        waited;

    initial begin
        nonce = {(8*64){1'b0}};
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) begin
            nonce = {(8*64){1'b0}};
        end
        waited = 0;
        while (!(done4 && done8) && waited < 100000) begin
            @(posedge aclk);
            waited = waited + 1;
        end
        passed = passed4 + passed8;
        failed = failed4 + failed8;
        if (!(done4 && done8)) begin
            $error("axil_timer_tb: timeout, lanes did not finish (done4=%0d done8=%0d)", done4, done8);
            failed = failed + 1;
        end
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: axil_timer_tb_lane.v ===
`timescale 1ns / 1ps
`default_nettype none

// One directed, self-checking test lane against one axil_timer instance.
// Inputs are driven 1 ns after a rising edge; a handshake happens on the
// next rising edge when valid and ready are both high. Cycle numbers count
// rising edges, so a write "takes effect" on edge wr_edge (the edge after
// which BVALID is first high) and irq_rise_cyc is the edge after which irq
// rose.
module axil_timer_tb_lane #(
    parameter integer ADDR_WIDTH = 4
) (
    input  wire        aclk,
    output reg         done,
    output reg  [31:0] passed,
    output reg  [31:0] failed
);

    localparam [1:0]  OKAY     = 2'b00;
    localparam [1:0]  SLVERR   = 2'b10;
    localparam [31:0] A_CTRL   = 32'h0;
    localparam [31:0] A_LOAD   = 32'h4;
    localparam [31:0] A_COUNT  = 32'h8;
    localparam [31:0] A_STATUS = 32'hC;

    reg                   aresetn;
    reg  [ADDR_WIDTH-1:0] s_axil_awaddr;
    reg                   s_axil_awvalid;
    wire                  s_axil_awready;
    reg  [31:0]           s_axil_wdata;
    reg  [3:0]            s_axil_wstrb;
    reg                   s_axil_wvalid;
    wire                  s_axil_wready;
    wire [1:0]            s_axil_bresp;
    wire                  s_axil_bvalid;
    reg                   s_axil_bready;
    reg  [ADDR_WIDTH-1:0] s_axil_araddr;
    reg                   s_axil_arvalid;
    wire                  s_axil_arready;
    wire [31:0]           s_axil_rdata;
    wire [1:0]            s_axil_rresp;
    wire                  s_axil_rvalid;
    reg                   s_axil_rready;
    wire                  irq;

    axil_timer #(.ADDR_WIDTH(ADDR_WIDTH)) dut (
        .aclk           (aclk),
        .aresetn        (aresetn),
        .s_axil_awaddr  (s_axil_awaddr),
        .s_axil_awvalid (s_axil_awvalid),
        .s_axil_awready (s_axil_awready),
        .s_axil_wdata   (s_axil_wdata),
        .s_axil_wstrb   (s_axil_wstrb),
        .s_axil_wvalid  (s_axil_wvalid),
        .s_axil_wready  (s_axil_wready),
        .s_axil_bresp   (s_axil_bresp),
        .s_axil_bvalid  (s_axil_bvalid),
        .s_axil_bready  (s_axil_bready),
        .s_axil_araddr  (s_axil_araddr),
        .s_axil_arvalid (s_axil_arvalid),
        .s_axil_arready (s_axil_arready),
        .s_axil_rdata   (s_axil_rdata),
        .s_axil_rresp   (s_axil_rresp),
        .s_axil_rvalid  (s_axil_rvalid),
        .s_axil_rready  (s_axil_rready),
        .irq            (irq)
    );

    // ------------------------------------------------------------------
    // Edge counter and irq rise monitor
    // ------------------------------------------------------------------
    integer cyc = 0;
    always @(posedge aclk) cyc <= cyc + 1;

    reg     irq_prev     = 1'b0;
    integer irq_rises    = 0;
    integer irq_rise_cyc = 0;
    always @(negedge aclk) begin
        irq_prev <= irq;
        if (irq === 1'b1 && irq_prev === 1'b0) begin
            irq_rises    <= irq_rises + 1;
            irq_rise_cyc <= cyc;
        end
    end

    // ------------------------------------------------------------------
    // Checking
    // ------------------------------------------------------------------
    task check(input cond, input integer id);
        begin
            if (cond === 1'b1) begin
                passed = passed + 32'd1;
            end else begin
                failed = failed + 32'd1;
                $error("axil_timer_tb[ADDR_WIDTH=%0d] check %0d failed at cycle %0d",
                       ADDR_WIDTH, id, cyc);
            end
        end
    endtask

    task check_eq(input [31:0] got, input [31:0] want, input integer id);
        begin
            if (got === want) begin
                passed = passed + 32'd1;
            end else begin
                failed = failed + 32'd1;
                $error("axil_timer_tb[ADDR_WIDTH=%0d] check %0d failed at cycle %0d: got 0x%08h, expected 0x%08h",
                       ADDR_WIDTH, id, cyc, got, want);
            end
        end
    endtask

    // ------------------------------------------------------------------
    // Bus helpers
    // ------------------------------------------------------------------
    function [ADDR_WIDTH-1:0] trunc_addr(input [31:0] a);
        begin
            trunc_addr = a[ADDR_WIDTH-1:0];
        end
    endfunction

    task step;
        begin
            @(posedge aclk);
            #1;
        end
    endtask

    task wait_cyc(input integer target);
        begin
            while (cyc < target) step;
        end
    endtask

    task wait_rise(input integer prev, input integer timeout);
        integer k;
        begin
            k = 0;
            while (irq_rises == prev && k < timeout) begin
                step;
                k = k + 1;
            end
        end
    endtask

    integer     wr_edge;
    reg  [1:0]  wr_resp;

    // order: 0 address and data together, 1 address first, 2 data first.
    // bdelay: cycles BREADY is held low after BVALID rises.
    task axi_write(input [31:0] addr, input [31:0] data, input [3:0] strb,
                   input integer order, input integer bdelay);
        reg     aw_t;
        reg     w_t;
        integer k;
        begin
            s_axil_awaddr  = trunc_addr(addr);
            s_axil_wdata   = data;
            s_axil_wstrb   = strb;
            s_axil_awvalid = (order != 2);
            s_axil_wvalid  = (order != 1);
            if (order != 0) begin
                for (k = 0; k < 2; k = k + 1) begin
                    aw_t = s_axil_awvalid && s_axil_awready;
                    w_t  = s_axil_wvalid  && s_axil_wready;
                    step;
                    if (aw_t) s_axil_awvalid = 1'b0;
                    if (w_t)  s_axil_wvalid  = 1'b0;
                end
                check(s_axil_bvalid === 1'b0, 900);
                if (order == 1) begin
                    check(s_axil_awready === 1'b0, 901);
                    s_axil_wvalid = 1'b1;
                end else begin
                    check(s_axil_wready === 1'b0, 902);
                    s_axil_awvalid = 1'b1;
                end
            end
            k = 0;
            while ((s_axil_awvalid || s_axil_wvalid) && k < 50) begin
                aw_t = s_axil_awvalid && s_axil_awready;
                w_t  = s_axil_wvalid  && s_axil_wready;
                step;
                if (aw_t) s_axil_awvalid = 1'b0;
                if (w_t)  s_axil_wvalid  = 1'b0;
                k = k + 1;
            end
            s_axil_awvalid = 1'b0;
            s_axil_wvalid  = 1'b0;
            check(s_axil_bvalid === 1'b1, 903);
            wr_edge = cyc;
            wr_resp = s_axil_bresp;
            for (k = 0; k < bdelay; k = k + 1) begin
                step;
                check(s_axil_bvalid === 1'b1 && s_axil_bresp === wr_resp &&
                      s_axil_awready === 1'b0 && s_axil_wready === 1'b0, 904);
            end
            s_axil_bready = 1'b1;
            step;
            s_axil_bready = 1'b0;
            check(s_axil_bvalid === 1'b0, 905);
        end
    endtask

    reg  [31:0] rd_data;
    reg  [1:0]  rd_resp;
    integer     rd_edge;

    // rdelay: cycles RREADY is held low after RVALID rises.
    task axi_read(input [31:0] addr, input integer rdelay);
        reg     ar_t;
        integer k;
        begin
            s_axil_araddr  = trunc_addr(addr);
            s_axil_arvalid = 1'b1;
            k = 0;
            while (s_axil_arvalid && k < 50) begin
                ar_t = s_axil_arready;
                step;
                if (ar_t) s_axil_arvalid = 1'b0;
                k = k + 1;
            end
            s_axil_arvalid = 1'b0;
            check(s_axil_rvalid === 1'b1, 910);
            rd_edge = cyc;
            rd_data = s_axil_rdata;
            rd_resp = s_axil_rresp;
            for (k = 0; k < rdelay; k = k + 1) begin
                step;
                check(s_axil_rvalid === 1'b1 && s_axil_rdata === rd_data &&
                      s_axil_rresp === rd_resp && s_axil_arready === 1'b0, 911);
            end
            s_axil_rready = 1'b1;
            step;
            s_axil_rready = 1'b0;
            check(s_axil_rvalid === 1'b0, 912);
        end
    endtask

    task expect_read(input [31:0] addr, input [31:0] want_data,
                     input [1:0] want_resp, input integer id);
        begin
            axi_read(addr, 0);
            check_eq(rd_data, want_data, id);
            check(rd_resp === want_resp, id + 1);
        end
    endtask

    task expect_write(input [31:0] addr, input [31:0] data, input [3:0] strb,
                      input [1:0] want_resp, input integer id);
        begin
            axi_write(addr, data, strb, 0, 0);
            check(wr_resp === want_resp, id);
        end
    endtask

    task clear_status;
        begin
            axi_write(A_STATUS, 32'h1, 4'h1, 0, 0);
            check(wr_resp === OKAY, 950);
        end
    endtask

    // One-shot count with LOAD n, timed to the edge.
    task oneshot_timed(input [31:0] n, input integer id);
        integer r0;
        integer s0;
        begin
            axi_write(A_LOAD, n, 4'hF, 0, 0);
            r0 = irq_rises;
            axi_write(A_CTRL, 32'h3, 4'h1, 0, 0);   // EN | IE, one-shot
            s0 = wr_edge;
            wait_rise(r0, 100);
            check_eq(irq_rises, r0 + 1, id);
            check_eq(irq_rise_cyc, s0 + ((n == 32'd0) ? 32'd1 : n), id + 1);
            expect_read(A_CTRL,   32'h2, OKAY, id + 2);   // EN cleared itself
            expect_read(A_COUNT,  32'h0, OKAY, id + 4);
            expect_read(A_STATUS, 32'h1, OKAY, id + 6);
            clear_status;
            check(irq === 1'b0, id + 8);
        end
    endtask

    // ------------------------------------------------------------------
    // Test sequence
    // ------------------------------------------------------------------
    integer    r;
    integer    t0;
    integer    t1;
    integer    t2;
    integer    p;
    reg [31:0] c1;

    initial begin
        done           = 1'b0;
        passed         = 32'd0;
        failed         = 32'd0;
        aresetn        = 1'b0;
        s_axil_awaddr  = {ADDR_WIDTH{1'b0}};
        s_axil_awvalid = 1'b0;
        s_axil_wdata   = 32'd0;
        s_axil_wstrb   = 4'd0;
        s_axil_wvalid  = 1'b0;
        s_axil_bready  = 1'b0;
        s_axil_araddr  = {ADDR_WIDTH{1'b0}};
        s_axil_arvalid = 1'b0;
        s_axil_rready  = 1'b0;
        r  = 0;
        t0 = 0;
        t1 = 0;
        t2 = 0;
        p  = 0;
        c1 = 32'd0;

        // ---- Reset
        repeat (3) @(posedge aclk);
        #1;
        check(s_axil_bvalid === 1'b0 && s_axil_rvalid === 1'b0 && irq === 1'b0, 1);
        aresetn = 1'b1;
        step;
        check(s_axil_awready === 1'b1 && s_axil_wready === 1'b1 && s_axil_arready === 1'b1, 2);

        // ---- Reset values
        expect_read(A_CTRL,   32'h0, OKAY, 10);
        expect_read(A_LOAD,   32'h0, OKAY, 12);
        expect_read(A_COUNT,  32'h0, OKAY, 14);
        expect_read(A_STATUS, 32'h0, OKAY, 16);

        // ---- LOAD with partial strobes, both channel orders, backpressure
        axi_write(A_LOAD, 32'hFFFF_FFFF, 4'hF, 0, 0);
        check(wr_resp === OKAY, 20);
        axi_write(A_LOAD, 32'h1234_5678, 4'h5, 1, 0);   // address first
        check(wr_resp === OKAY, 21);
        expect_read(A_LOAD, 32'hFF34_FF78, OKAY, 22);
        axi_write(A_LOAD, 32'hAABB_CCDD, 4'hA, 2, 3);   // data first, B held off
        check(wr_resp === OKAY, 24);
        expect_read(A_LOAD, 32'hAA34_CC78, OKAY, 25);
        axi_write(A_LOAD, 32'h0000_0000, 4'h0, 0, 2);   // no strobes
        check(wr_resp === OKAY, 27);
        axi_read(A_LOAD, 4);                            // R held off
        check_eq(rd_data, 32'hAA34_CC78, 28);
        check(rd_resp === OKAY, 29);

        // ---- CTRL: no wstrb[0] changes nothing; upper bits read as zero
        expect_write(A_CTRL, 32'h0000_0007, 4'hE, OKAY, 30);
        expect_read(A_CTRL,  32'h0, OKAY, 31);
        expect_read(A_COUNT, 32'h0, OKAY, 33);
        expect_write(A_CTRL, 32'hFFFF_FFF6, 4'hF, OKAY, 35);
        expect_read(A_CTRL,  32'h6, OKAY, 36);
        expect_write(A_CTRL, 32'h0, 4'h1, OKAY, 38);
        expect_read(A_CTRL,  32'h0, OKAY, 39);

        // ---- COUNT read only, SLVERR policy, no aliasing
        expect_write(A_COUNT, 32'h0000_1234, 4'hF, SLVERR, 42);
        expect_write(A_COUNT, 32'h0000_1234, 4'h0, SLVERR, 43);
        expect_read(A_COUNT, 32'h0, OKAY, 44);
        expect_write(32'h5, 32'h0, 4'hF, SLVERR, 46);
        expect_write(32'h1, 32'h7, 4'hF, SLVERR, 47);
        expect_write(32'hE, 32'h1, 4'hF, SLVERR, 48);
        expect_read(A_LOAD, 32'hAA34_CC78, OKAY, 49);
        expect_read(A_CTRL, 32'h0, OKAY, 51);
        expect_read(32'h2, 32'h0, SLVERR, 53);
        expect_read(32'h6, 32'h0, SLVERR, 55);
        expect_read(32'h7, 32'h0, SLVERR, 57);
        if (ADDR_WIDTH > 4) begin
            expect_write(32'h14, 32'h0, 4'hF, SLVERR, 60);
            expect_write(32'h10, 32'h7, 4'hF, SLVERR, 61);
            expect_write(32'hF4, 32'h0, 4'hF, SLVERR, 62);
            expect_read(A_LOAD, 32'hAA34_CC78, OKAY, 63);
            expect_read(A_CTRL, 32'h0, OKAY, 65);
            expect_read(32'h14, 32'h0, SLVERR, 67);
            expect_read(32'h10, 32'h0, SLVERR, 69);
            expect_read(32'h1C, 32'h0, SLVERR, 71);
            expect_read(32'hF4, 32'h0, SLVERR, 73);
        end

        // ---- One-shot counts timed to the edge
        oneshot_timed(32'd5,  80);
        oneshot_timed(32'd1,  90);
        oneshot_timed(32'd0,  100);
        oneshot_timed(32'd17, 110);

        // ---- STATUS clear rules and no second interrupt
        axi_write(A_LOAD, 32'd4, 4'hF, 0, 0);
        r = irq_rises;
        axi_write(A_CTRL, 32'h3, 4'h1, 0, 0);
        wait_rise(r, 50);
        check(irq === 1'b1, 120);
        expect_write(A_STATUS, 32'h0, 4'hF, OKAY, 121);   // writing 0 keeps it
        expect_write(A_STATUS, 32'h1, 4'hE, OKAY, 122);   // no wstrb[0] keeps it
        expect_read(A_STATUS, 32'h1, OKAY, 123);
        check(irq === 1'b1, 125);
        expect_write(A_STATUS, 32'h1, 4'h1, OKAY, 126);
        check(irq === 1'b0, 127);
        expect_read(A_STATUS, 32'h0, OKAY, 128);
        r = irq_rises;
        repeat (40) step;
        check_eq(irq_rises, r, 130);
        check(irq === 1'b0, 131);
        expect_read(A_STATUS, 32'h0, OKAY, 132);
        expect_read(A_CTRL,   32'h2, OKAY, 134);

        // ---- Interrupt enable on a pending expiry
        axi_write(A_LOAD, 32'd3, 4'hF, 0, 0);
        axi_write(A_CTRL, 32'h1, 4'h1, 0, 0);   // EN, IE off
        repeat (10) step;
        expect_read(A_STATUS, 32'h1, OKAY, 140);
        check(irq === 1'b0, 142);
        r = irq_rises;
        axi_write(A_CTRL, 32'h2, 4'h1, 0, 0);   // IE on
        t0 = wr_edge;
        check(irq === 1'b1, 143);
        check_eq(irq_rises, r + 1, 144);
        check_eq(irq_rise_cyc, t0, 145);
        axi_write(A_CTRL, 32'h0, 4'h1, 0, 0);   // IE off
        check(irq === 1'b0, 146);
        expect_read(A_STATUS, 32'h1, OKAY, 147);
        axi_write(A_CTRL, 32'h2, 4'h1, 0, 0);   // IE on again
        check(irq === 1'b1, 149);
        clear_status;
        check(irq === 1'b0, 150);

        // ---- Periodic counts timed over several periods
        axi_write(A_LOAD, 32'd10, 4'hF, 0, 0);
        r = irq_rises;
        axi_write(A_CTRL, 32'h7, 4'h1, 0, 0);   // EN | IE | MODE
        t0 = wr_edge;
        for (p = 1; p <= 3; p = p + 1) begin
            wait_rise(r, 50);
            check_eq(irq_rises, r + 1, 160);
            check_eq(irq_rise_cyc, t0 + 10 * p, 161);
            r = irq_rises;
            clear_status;
            check(irq === 1'b0, 162);
        end
        expect_read(A_CTRL, 32'h7, OKAY, 163);
        // A clear landing on the edge a count ends: the expiry is kept.
        r = irq_rises;
        wait_cyc(t0 + 39);
        axi_write(A_STATUS, 32'h1, 4'h1, 0, 0);
        check_eq(wr_edge, t0 + 40, 165);
        expect_read(A_STATUS, 32'h1, OKAY, 166);
        check(irq === 1'b1, 168);
        check_eq(irq_rises, r + 1, 169);
        check_eq(irq_rise_cyc, t0 + 40, 170);

        // ---- Stop freezes COUNT
        axi_write(A_CTRL, 32'h6, 4'h1, 0, 0);   // EN 0, IE and MODE kept
        clear_status;
        r = irq_rises;
        axi_read(A_COUNT, 0);
        c1 = rd_data;
        check(rd_resp === OKAY && c1 <= 32'd10, 172);
        repeat (25) step;
        expect_read(A_COUNT, c1, OKAY, 173);
        expect_write(A_COUNT, 32'hFFFF_FFFF, 4'hF, SLVERR, 175);
        expect_read(A_COUNT, c1, OKAY, 176);
        check_eq(irq_rises, r, 178);
        expect_read(A_STATUS, 32'h0, OKAY, 179);
        expect_read(A_CTRL,   32'h6, OKAY, 181);
        check(irq === 1'b0, 183);

        // ---- Restart from LOAD
        axi_write(A_LOAD, 32'd6, 4'hF, 0, 0);
        r = irq_rises;
        axi_write(A_CTRL, 32'h3, 4'h1, 0, 0);
        t1 = wr_edge;
        axi_write(A_CTRL, 32'h3, 4'h1, 0, 0);   // restart while counting
        t2 = wr_edge;
        check(t2 > t1 && t2 < t1 + 6, 185);
        wait_rise(r, 50);
        check_eq(irq_rises, r + 1, 186);
        check_eq(irq_rise_cyc, t2 + 6, 187);
        expect_read(A_CTRL, 32'h2, OKAY, 188);
        clear_status;

        // ---- Reset during a count (and with a write address held)
        axi_write(A_LOAD, 32'd100, 4'hF, 0, 0);
        axi_write(A_CTRL, 32'h7, 4'h1, 0, 0);
        repeat (5) step;
        s_axil_awaddr  = trunc_addr(A_LOAD);
        s_axil_awvalid = 1'b1;
        step;
        s_axil_awvalid = 1'b0;
        check(s_axil_awready === 1'b0 && s_axil_bvalid === 1'b0, 190);
        aresetn = 1'b0;
        step;
        step;
        check(s_axil_bvalid === 1'b0 && s_axil_rvalid === 1'b0 && irq === 1'b0, 191);
        check(s_axil_awready === 1'b1 && s_axil_wready === 1'b1, 192);
        aresetn = 1'b1;
        step;
        expect_read(A_CTRL,   32'h0, OKAY, 193);
        expect_read(A_LOAD,   32'h0, OKAY, 195);
        expect_read(A_COUNT,  32'h0, OKAY, 197);
        expect_read(A_STATUS, 32'h0, OKAY, 199);
        // The held address was dropped: data alone must not complete a write.
        s_axil_wdata  = 32'h0000_0055;
        s_axil_wstrb  = 4'hF;
        s_axil_wvalid = 1'b1;
        step;
        s_axil_wvalid = 1'b0;
        check(s_axil_bvalid === 1'b0 && s_axil_wready === 1'b0, 201);
        step;
        step;
        check(s_axil_bvalid === 1'b0, 202);
        s_axil_awaddr  = trunc_addr(A_LOAD);
        s_axil_awvalid = 1'b1;
        step;
        s_axil_awvalid = 1'b0;
        check(s_axil_bvalid === 1'b1 && s_axil_bresp === OKAY, 203);
        s_axil_bready = 1'b1;
        step;
        s_axil_bready = 1'b0;
        check(s_axil_bvalid === 1'b0, 204);
        expect_read(A_LOAD, 32'h0000_0055, OKAY, 205);
        r = irq_rises;
        repeat (120) step;
        check_eq(irq_rises, r, 207);
        expect_read(A_STATUS, 32'h0, OKAY, 208);
        expect_read(A_COUNT,  32'h0, OKAY, 210);
        expect_read(A_CTRL,   32'h0, OKAY, 212);

        done = 1'b1;
    end

endmodule

`default_nettype wire
